const localSprites={"25":"data:image/png;base64,","278":"data:image/png;base64,","131":"data:image/png;base64,","133":"data:image/png;base64,","7":"data:image/png;base64,","153":"data:image/png;base64,","50":"data:image/png;base64,","506":"data:image/png;base64,","222":"data:image/png;base64,","352":"data:image/png;base64,","418":"data:image/png;base64,"};
