const sources=(id,shiny,style)=>[...(!shiny&&style==='sprite'&&localSprites[id]?[localSprites[id]]:[]),...[style,style==='art'?'sprite':'art'].flatMap(t=>hosts.map(h=>h+(t==='art'?'other/official-artwork/':'')+(shiny?'shiny/':'')+id+'.png')),...(!shiny&&style==='art'&&localSprites[id]?[localSprites[id]]:[])];
const image=(id,shiny=false,style='art',eager=false)=>`<div class="poke-image ${style==='sprite'?'pixel':''}"><span class="fallback" aria-hidden="true"><i class="ball"></i><small>#${pad(id)}</small></span><img ${eager?'':'loading="lazy"'} decoding="async" alt="${escape(D.species[id]?.name||'Pokémon')} ${shiny?'shiny':''}" src="${sources(id,shiny,style)[0]}" data-poke="${id}" data-shiny="${shiny?1:0}" data-style="${style}"></div>`;
