const fail=new Set(),good=new Set();
function loaded(img){img.classList.add('ready');img.previousElementSibling.hidden=true;if(img.src.startsWith('data:'))img.classList.add('local-sprite');else good.add(img.dataset.poke+'-'+img.dataset.shiny);if(good.size){$('image-status').hidden=true;}}
document.addEventListener('load',e=>{if(e.target instanceof HTMLImageElement&&e.target.dataset.poke)loaded(e.target)},true);
document.addEventListener('error',e=>{let img=e.target;if(!(img instanceof HTMLImageElement)||!img.dataset.poke)return;let urls=sources(+img.dataset.poke,img.dataset.shiny==='1',img.dataset.style);let stage=+(img.dataset.stage||0)+1;if(stage<urls.length){img.dataset.stage=stage;img.src=urls[stage]}else{img.hidden=true;fail.add(img.dataset.poke+'-'+img.dataset.shiny);if(!good.size&&fail.size>=2){$('image-status').textContent='Imagens indisponíveis. Confira sua conexão ou tente abrir o aplicativo em outro navegador. A jornada continua funcionando.';$('image-status').hidden=false;}}},true);
// Usa a espécie citada no evento, não a forma atual do companheiro.
const speciesList=Object.values(D.species).sort((a,b)=>b.name.length-a.name.length);
function eventVisual(e){if(e.mystery?.stage==='incubating'||e.mystery?.stage==='research')return [];if(e.trade)return [e.trade.out,e.trade.in];let ids=[];let t=e.title+' '+e.text;for(const sp of speciesList){let pattern=sp.name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');if(new RegExp('(?:^|[^\\p{L}\\p{N}])'+pattern+'(?=$|[^\\p{L}\\p{N}])','iu').test(t))ids.push(sp.id)}let mons=e.pokemon.map(uid=>e.snapshot.pokemon.find(p=>p.uid===uid)).filter(Boolean);let before=state.events[state.events.indexOf(e)-1]?.snapshot.pokemon||[];let evos=mons.map(p=>({from:before.find(q=>q.uid===p.uid)?.id,to:p.id})).filter(x=>x.from&&x.from!==x.to);if(e.kind==='evolution'&&evos.length){let ev=evos.find(x=>ids.includes(x.from)&&ids.includes(x.to))||evos[0];return [ev.from,ev.to].map(id=>({id,shiny:mons.some(p=>p.shiny)}))}if(!ids.length)for(let uid of e.pokemon){let p=e.snapshot.pokemon.find(p=>p.uid===uid);if(p)ids.push(p.id)}return [...new Set(ids)].slice(0,3).map(id=>({id,shiny:e.kind==='shiny'||(e.kind==='legend'&&e.text.includes('cores extraordinárias'))||mons.some(p=>p.shiny&&(p.id===id))}))}
const symbols={egg:'◉',hatch:'✦',fossil:'◈',secret:'?',connected:'♥',trade:'⇄','trade-offer':'⇄',news:'▤',item:'◈',expedition:'⌖',arc:'✧',relationship:'♥',birth:'✦',family:'⌂',capture:'●',encounter:'◎',evolution:'↗',shiny:'✦',legend:'✧',career:'▣',memory:'◆',bond:'♥',social:'♟',competition:'★',battle:'⚔',status:'↔',farewell:'↗',world:'◉',festival:'★',study:'▤',route:'➜',training:'⚑'};
