function toast(msg){clearTimeout(toastTimer);text('toast',msg);$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3500)}
$('species-count').textContent=Object.keys(D.species).length;$('birth').max=E.today();$('city').innerHTML='<option value="">Escolha sua cidade</option>'+D.cities.map(c=>`<option value="${c.id}">${escape(c.name)}</option>`).join('');$('city').addEventListener('change',()=>text('city-hint',D.cities.find(c=>c.id===$('city').value)?.tag||''));
$('form').addEventListener('submit',e=>{e.preventDefault();text('error','');try{if(pairMode){startPair(readPairInputs());return}generate({name:$('name').value,birth:$('birth').value,cityId:$('city').value,personality:$('personality').value,universe:0});persist()}catch(err){text('error',err.message)}});
function generate(input,resume=null){$('pair-result').hidden=true;state=E.simulate(input);cursor=0;step=0;finished=false;if(resume){let pos=state.events.findIndex(e=>e.id===resume.eventId);cursor=pos>=0?pos:0;step=Math.max(0,Math.min(Number(resume.step)||0,battleSteps(state.events[cursor].battle)));finished=!!resume.finished&&cursor===state.events.length-1;if(resume.finished&&!finished&&pos>=0){cursor=Math.min(pos+1,state.events.length-1);step=0}}$('welcome').hidden=true;$('result').hidden=false;tab='life';render();window.scrollTo({top:0,behavior:'instant'});}
function persist(announce=false){try{localStorage.setItem(storage,JSON.stringify({version:E.version,input:inputFromState(),eventId:state.events[cursor].id,step,finished}));if(announce)toast('Progresso salvo neste navegador.')}catch{if(announce)toast('Não foi possível salvar neste navegador.')}}
function render(){document.querySelector('.tabs').hidden=!finished;$('export').hidden=!finished;$('summary').hidden=!finished;$('team-preview').hidden=!finished;if(finished){$('result').classList.remove('reading');renderFinal();return}$('result').classList.add('reading');text('result-title',state.name);text('subtitle',state.city+' · Diário em andamento');text('universe-label',state.universe?` / UNIVERSO ${state.universe+1}`:' / UNIVERSO ORIGINAL');$('titles').innerHTML='';$('summary').innerHTML='';$('team-preview').innerHTML='';renderChapter()}
function battleMon(mon){let sp=D.species[mon.id];return `<div class="combatant ${mon.shiny?'shiny':''}">${image(mon.id,mon.shiny,'sprite',true)}<b>${escape(sp.name)}${mon.shiny?' ✦':''}</b>${typeChip(sp)}</div>`}
function duelCard(d,i,revealed=true){return `<div class="duel"><div class="duel-label">DUELO ${i+1} <span>${revealed?(d.won?'VITÓRIA':'DERROTA'):'EM ANDAMENTO'}</span></div><div class="versus">${battleMon(d.player)}<div class="vs">VS</div>${battleMon(d.opponent)}</div>${revealed?`<div class="duel-result ${d.won?'win':'loss'}"><b>${escape(D.species[d.won?d.player.id:d.opponent.id].name)} venceu</b><span>+${d.xp} EXP para ${escape(D.species[d.player.id].name)}</span><p>${escape(d.scene)}</p></div>${d.turns?turnReplay(d):''}`:''}</div>`}
function turnReplay(d){return `<details class="turn-log"><summary>Rever os momentos do duelo</summary>${d.turns.map((t,i)=>`<div class="turn-row"><span class="turn-num">${i+1}</span><div><p>${escape(t.text)}</p><div class="hp-pair"><div><small>${escape(D.species[d.player.id].name)} · ${t.player}%</small>${meter(t.player)}</div><div><small>${escape(D.species[d.opponent.id].name)} · ${t.opponent}%</small>${meter(t.opponent)}</div></div></div></div>`).join('')}</details>`}
function badgeIcon(g,earned){let col=colors[g.type]||'#8593a4';let paths=['M12 32 Q20 18 28 32 T44 32 T60 32','M35 13 L22 36 H34 L28 53 L48 28 H35 Z','M32 12 V52 M15 22 L49 42 M15 42 L49 22','M32 48 Q9 39 18 18 Q43 15 46 29 Q45 43 32 48 M32 48 L35 25','M32 12 L48 25 L42 48 L22 48 L16 25 Z','M18 32 L25 20 L39 20 L46 32 L39 44 L25 44 Z M25 32 H39','M13 40 Q20 12 49 20 Q42 42 13 40 M17 46 L42 25','M12 32 Q32 10 52 32 Q32 54 12 32 Z M32 24 A8 8 0 1 0 32 40 A8 8 0 1 0 32 24'];return `<svg class="gym-badge ${earned?'earned':'locked'}" viewBox="0 0 64 64" aria-hidden="true"><path d="M32 3 L57 17 V47 L32 61 L7 47 V17Z" fill="${earned?col:'#cbd2dd'}" stroke="${earned?'#f6d585':'#aab5c5'}" stroke-width="3"/><path d="${paths[g.order]}" fill="none" stroke="white" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function leaguePanel(snap,final=false){let badges=snap.badges||[],gyms=snap.gyms||{},league=snap.league||{},rivals=snap.rivals||[];return `<div class="league-hub"><div class="league-heading"><div><span class="eyebrow">CIRCUITO REGIONAL</span><h2>Liga das Lagoas</h2><p>${badges.length}/8 insígnias conquistadas${league.champion?' · Campeão regional':''}</p></div><div class="league-count">${badges.length}<small>/8</small></div></div><div class="badge-case">${D.gyms.map(g=>{let b=badges.find(x=>x.id===g.id),rec=gyms[g.id];return `<div class="badge-slot">${badgeIcon(g,!!b)}<b>${escape(g.badge)}</b><small>${escape(city(g.city))}</small><small>${b?'Conquistada aos '+b.age+' anos':rec?rec.attempts+' tentativa(s)':'Não conquistada'}</small>${rec?`<small>${rec.wins}V · ${rec.losses}D · ${rec.draws}E</small>`:''}</div>`}).join('')}</div><div class="league-stage"><h3>O caminho para o campeonato</h3><p>${badges.length<8?'As oito insígnias liberam o desafio da Elite dos Quatro.':league.champion?'Você conquistou a Liga das Lagoas.':'Classificado para a Liga · etapas superadas: '+(league.stage||0)+'/5'}</p><div class="elite-track">${D.elite.map((g,i)=>`<div class="${(league.stage||0)>i?'cleared':''}"><strong>${(league.stage||0)>i?'✓':i+1}</strong><small>${i===4?'Final':'Elite '+(i+1)}</small></div>`).join('')}</div></div><h3>Rivais conhecidos</h3>${rivals.length?rivals.map(f=>`<div class="rival-card"><div><b>${escape(f.name)}</b><p>Desde os ${f.metAge} anos · seu retrospecto: ${f.wins}V / ${f.losses}D / ${f.draws}E</p><small>${f.bond>=65?'Rivalidade com amizade':'Rivalidade em desenvolvimento'}</small></div><div class="rival-team">${f.team.map(p=>`<div>${image(p.id,p.shiny,'sprite')}<small>${escape(D.species[p.id].name)}</small></div>`).join('')}</div></div>`).join(''):'<p class="panel-intro">Nenhum rival conhecido até aqui.</p>'}</div>`}
function renderLeague(){$('panel').innerHTML=leaguePanel(state,true)}
function battleSteps(b){return b?b.duels.reduce((n,d)=>n+(d.turns?.length||2),0):0}
function battleState(b,position){let total=battleSteps(b),ended=position>=total,remaining=position,idx=0;while(idx<b.duels.length-1&&remaining>=(b.duels[idx].turns?.length||2)){remaining-=b.duels[idx].turns?.length||2;idx++}let d=b.duels[idx],size=d.turns?.length||2,turn=ended?size-1:Math.min(remaining,size-1),revealed=ended||turn===size-1;return {ended,idx,turn,revealed,completed:b.duels.slice(0,ended?b.duels.length:idx+(revealed?1:0))}}
function liveDuel(d,idx,turn,revealed){if(!d.turns)return duelCard(d,idx,revealed);let t=d.turns[turn];return `<div class="duel"><div class="duel-label">DUELO ${idx+1} · MOMENTO ${turn+1}/${d.turns.length}<span>${revealed?(d.won?'VITÓRIA':'DERROTA'):'EM ANDAMENTO'}</span></div><div class="versus">${battleMon(d.player)}<div class="vs">VS</div>${battleMon(d.opponent)}</div><div class="live-hp hp-pair"><div><small>Seu Pokémon · HP ${t.player}%</small>${meter(t.player)}</div><div><small>Adversário · HP ${t.opponent}%</small>${meter(t.opponent)}</div></div><p class="turn-narrative">${escape(t.text)}</p>${revealed?`<div class="duel-result ${d.won?'win':'loss'}"><b>${escape(D.species[d.won?d.player.id:d.opponent.id].name)} venceu</b><span>+${d.xp} EXP para ${escape(D.species[d.player.id].name)}</span></div>`:''}</div>`}
function chapterBattle(e){let b=e.battle,{ended,idx,turn,revealed,completed}=battleState(b,step);let w=completed.filter(d=>d.won).length,l=completed.length-w;return `<div class="battle-arena"><div class="battle-banner"><div><span class="eyebrow">${escape(b.format.toUpperCase())}</span><h3>Você × ${escape(b.rival)}</h3>${b.previous?`<small>${b.previous+1}º confronto neste histórico</small>`:''}</div><div class="score">${w} : ${l}</div></div><div class="battle-tracker">${b.duels.map((d,i)=>`<span class="${i<completed.length?(d.won?'win':'loss'):i===idx?'current':''}">${i+1}</span>`).join('')}</div>${liveDuel(b.duels[idx],idx,turn,revealed)}${ended?`<div class="battle-end ${b.result}"><strong>${b.result==='win'?'VITÓRIA!':b.result==='loss'?'DERROTA':'EMPATE'}</strong><p>${escape(N.text(e))}</p>${b.award?`<div class="award-reveal">${badgeIcon(D.gyms.find(g=>g.id===b.award.id),true)}<b>${escape(b.award.name)}</b></div>`:''}</div><details><summary>Rever todos os duelos</summary>${b.duels.map((d,i)=>duelCard(d,i)).join('')}</details>`:''}</div>`}
function partyNow(pokemon){let arr=pokemon.filter(p=>p.status==='active');return `<div class="journey-team"><div class="team-bar"><div><span class="eyebrow">${arr.length}/6 · EQUIPE NESTE MOMENTO</span><h3>Seus companheiros</h3></div></div><div class="party-grid">${Array.from({length:6},(_,i)=>{let p=arr[i];if(!p)return `<div class="party-slot empty-slot"><span class="ball"></span><small>Slot livre</small></div>`;let sp=D.species[p.id];return `<button type="button" data-progress-uid="${p.uid}" class="party-slot ${p.shiny?'shiny':''}" style="--type:${colors[sp.type]||'#8490a1'}">${image(p.id,p.shiny,'sprite',true)}<b>${escape(sp.name)}${p.shiny?' ✦':''}</b>${typeChip(sp)}<small>EXP de batalha: ${p.battleXP}</small></button>`}).join('')}</div></div>`}
function focusChapter(root){let el=root.querySelector('.journey-progress');if(el&&el.getBoundingClientRect().top<0)el.scrollIntoView({block:'start',behavior:'instant'})}
function storyCopy(e){return `<div class="story-copy">${N.paragraphs(N.text(e)).map(p=>`<p class="chapter-text">${escape(p)}</p>`).join('')}</div>`}
function memoryNote(e,cut){let src=e.source&&state.events.slice(0,cut).find(x=>x.id===e.source);return src?`<details class="memory-note"><summary>↳ Recordar: ${escape(src.title)} · ${src.age} anos</summary><p>${escape(N.text(src))}</p></details>`:''}
function chapterAtmosphere(e){return `<div class="chapter-location"><span>◆ ${escape(e.place||city(e.city)||'Região das Lagoas')}</span><span>${escape(e.season||E.seasonOf(e.date))}</span></div>`}
function changes(before,after){let prior=new Map((before?.pokemon||[]).map(p=>[p.uid,p])),now=after?.pokemon||[],out=[];for(let p of now){let old=prior.get(p.uid),name=D.species[p.id]?.name;if(!old)out.push(`Novo companheiro: ${name} · ${status[p.status]}`);else if(old.id!==p.id)out.push(`${D.species[old.id].name} → ${name}`);else if(old.status!==p.status)out.push(`${name} · ${status[p.status]}`)}return out.length?`<div class="chapter-changes"><span>O QUE MUDOU NESTE CAPÍTULO</span>${out.map(x=>`<div>✦ ${escape(x)}</div>`).join('')}</div>`:''}
let playbackTimer=null,playbackKey=null;
function stopBattlePlayback(){clearTimeout(playbackTimer);playbackTimer=null;playbackKey=null;}
function bindBattlePlayback(root,key,advance,skip){const controls=root.querySelector('.journey-controls');if(!controls)return;const bar=document.createElement('div');bar.className='battle-playback';bar.innerHTML='<button type="button" class="ghost battle-play">▶ Reproduzir batalha</button><button type="button" class="ghost battle-skip">Pular animação »</button>';controls.before(bar);const play=bar.querySelector('.battle-play'),skipButton=bar.querySelector('.battle-skip');function sync(){const playing=playbackKey===key;play.textContent=playing?'⏸ Pausar batalha':'▶ Reproduzir batalha';play.setAttribute('aria-pressed',String(playing));clearTimeout(playbackTimer);if(playing)playbackTimer=setTimeout(()=>{if(playbackKey!==key||!bar.isConnected||root.closest('[hidden]')||document.querySelector('dialog[open]')){stopBattlePlayback();play.textContent='▶ Reproduzir batalha';play.setAttribute('aria-pressed','false');return;}advance();},1700);}play.onclick=()=>{if(playbackKey===key)stopBattlePlayback();else{stopBattlePlayback();playbackKey=key;}sync();};skipButton.onclick=()=>{stopBattlePlayback();skip();};sync();}
function renderChapter(){let e=state.events[cursor],b=e.battle,bs=b?battleState(b,step):null,ended=!b||bs.ended;let snap=ended?e.snapshot:(state.events[cursor-1]?.snapshot||{pokemon:[],seen:[],wins:0,losses:0,career:null});if(b&&!ended){let revealed=bs.completed;snap={...snap,pokemon:snap.pokemon.map(p=>({...p,battleXP:p.battleXP+revealed.filter(d=>d.uid===p.uid).reduce((sum,d)=>sum+d.xp,0)}))}}let progress=Math.round((cursor+1)/state.events.length*100),visual=b?[]:eventVisual(e);let prev=state.events[cursor-1],newPhase=!prev||E.phase(prev.age)!==E.phase(e.age);let heading=b?'Um desafio na arena':N.title(e,D);
 $('panel').innerHTML=`<div class="journey-progress"><div><b>${e.age===0?'Nascimento':e.age+' anos'}</b><span>${escape(E.phase(e.age))} · ${date(e.date)}</span></div><div><span>Capítulo ${cursor+1} de ${state.events.length}</span><div class="meter"><span style="width:${progress}%"></span></div></div></div>${newPhase?`<div class="phase-banner">${escape(E.phase(e.age).toUpperCase())}</div>`:''}<div class="journey-layout"><article class="chapter-card kind-${escape(e.kind)}"><div class="chapter-kicker"><span>${escape(kinds[e.kind]||e.kind)}</span><span>${escape(city(e.city))} · ${escape(e.season||'')}</span></div><h2>${escape(heading)}</h2>${chapterAtmosphere(e)}${b?chapterBattle(e):`${e.trade?tradeCard(e.trade):`<div class="chapter-visual ${e.kind==='evolution'?'evolution-flash':''}">${e.mystery?.stage==='incubating'?eggArt():e.mystery?.stage==='research'?fossilArt():visual.length?visual.map((v,i)=>`${i&&['evolution','trade'].includes(e.kind)?'<span class="evo-arrow">→</span>':''}<div class="chapter-mon">${image(v.id,v.shiny,'sprite',true)}<b>${escape(D.species[v.id].name)}${v.shiny?' ✦':''}</b>${typeChip(D.species[v.id])}</div>`).join(''):`<span class="chapter-symbol">${symbols[e.kind]||'◆'}</span>`}</div>`}${storyCopy(e)}${memoryNote(e,cursor)}${e.arc?`<div class="arc-inline"><span>✧ ${escape(e.arc.stage)}</span><b>${escape(arcStatus[e.arc.status])}</b></div>`:''}${e.expedition?`<div class="exp-steps">${['Preparativos','Em campo','Retorno'].map((x,i)=>`<span class="${i<e.expedition.stage?'seen':''}">${i<e.expedition.stage?escape(x):'?'}</span>`).join('')}</div>`:''}${e.kind==='relationship'?relationshipCards(snap,(snap.relationships||[]).filter(x=>e.pokemon.includes(x.a)&&e.pokemon.includes(x.b))):''}`}${ended?changes(prev?.snapshot,snap):''}</article><div class="journey-controls"><button class="ghost" id="prev-chapter" ${cursor===0&&step===0?'disabled':''}>← Voltar</button><button class="primary" id="next-chapter">${!ended?(bs.revealed?(step===battleSteps(b)-1?'Ver resultado da batalha':'Próximo confronto'):(b.duels[bs.idx].turns?'Continuar batalha':'Revelar resultado do duelo')):cursor===state.events.length-1?'Revelar minha biografia →':'Continuar jornada →'}</button></div><aside class="journey-side">${partyNow(snap.pokemon)}<div class="journey-record"><span>${snap.seen.length} espécies registradas</span><span>${snap.wins} vitórias · ${snap.losses} derrotas</span><button class="ghost" id="progress-mystery">Ovos, fósseis e mistérios</button><button class="ghost" id="progress-world">Mapa, jornal e trocas</button><button class="ghost" id="progress-dex">Pokédex até aqui</button><button class="ghost" id="progress-bonds">Laços e histórias · ${(snap.arcs||[]).length}</button><button class="ghost" id="progress-league">Insígnias e rivais · ${(snap.badges||[]).length}/8</button></div></aside></div>`;
 document.querySelectorAll('[data-progress-uid]').forEach(b=>b.onclick=()=>detail(b.dataset.progressUid,ended?cursor:cursor-1));$('prev-chapter').onclick=()=>{stopBattlePlayback();if(step>0)step--;else if(cursor>0){cursor--;step=battleSteps(state.events[cursor].battle)}render();persist()};$('next-chapter').onclick=()=>{stopBattlePlayback();if(!ended)step++;else if(cursor<state.events.length-1){cursor++;step=0}else{finished=true;tab='life'}render();persist();if(!finished&&ended)focusChapter($('panel'));if(finished)window.scrollTo({top:0,behavior:'instant'})};$('progress-bonds').onclick=()=>{let cut=ended?cursor:cursor-1;$('detail-body').innerHTML=bondsPanel(snap,cut);bindBio(cut);$('detail').showModal()};$('progress-league').onclick=()=>{$('detail-body').innerHTML=leaguePanel(snap);$('detail').showModal()};$('progress-mystery').onclick=()=>openMysteries(snap);$('progress-world').onclick=()=>{let cut=ended?cursor:cursor-1;$('detail-body').innerHTML=worldPanel(cut);bindWorld(cut);$('detail').showModal()};$('progress-dex').onclick=()=>{$('detail-body').innerHTML=`<h2>Pokédex até este capítulo</h2><p class="panel-intro">Somente espécies já registradas.</p><div class="poke-grid">${snap.seen.map(x=>`<div class="poke">${image(x.id,!!x.shiny,'sprite')}<b>${escape(D.species[x.id].name)}</b>${typeChip(D.species[x.id])}</div>`).join('')||'<p>Nenhuma espécie registrada ainda.</p>'}</div>`;$('detail').showModal()};
 if(!ended)bindBattlePlayback($('panel'),'single:'+e.id,()=>{step++;render();persist()},()=>{step=battleSteps(b);render();persist()});else stopBattlePlayback();
 DC_VISUALS.decorate($('panel'),e,prev?.snapshot,visual,image,'single:'+state.name+'|'+state.birth+'|'+state.cityId+'|'+state.universe+'|'+e.id);
}
function renderFinal(){text('result-title',state.name);text('subtitle',`${state.age} ${state.age===1?'ano':'anos'} · ${state.city} · ${state.career||'Uma vida ainda em construção'}`);text('universe-label',state.universe?` / UNIVERSO ${state.universe+1}`:' / UNIVERSO ORIGINAL');$('titles').innerHTML=state.titles.map(t=>`<span class="chip">${escape(t)}</span>`).join('');const stats=[[state.pokemon.length,'Companheiros na vida'],[state.pokemon.filter(p=>p.status==='active').length,'Time atual'],[Object.keys(state.seen).length,'Espécies registradas'],[state.pokemon.reduce((a,p)=>a+p.evolutions.length,0),'Evoluções'],[state.shinySeen,'Shiny encontrados'],[state.legendSeen,'Encontros extraordinários']];$('summary').innerHTML=stats.map(([v,l])=>`<div class="stat"><b>${v}</b><span>${l}</span></div>`).join('');renderTeamPreview();renderTab()}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{tab=b.dataset.tab;renderTab()}));function renderTab(){document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('selected',b.dataset.tab===tab);b.setAttribute('aria-pressed',String(b.dataset.tab===tab))});const map={mystery:()=>{$('panel').innerHTML=mysteryPanel(state.events.at(-1).snapshot);},life:renderLife,team:renderTeam,dex:renderDex,profile:renderProfile,world:renderWorld,league:renderLeague,bonds:renderBonds};map[tab]()}
function renderLife(){ $('panel').innerHTML=`<div class="toolbar"><div><h2>Seu diário de vida</h2><p class="panel-intro">Cada capítulo tem uma data e um lugar. Algumas lembranças nunca desaparecem.</p></div><select id="filter-life" aria-label="Filtrar acontecimentos"><option value="all">Todos os acontecimentos</option><option value="major">Memórias importantes</option><option value="capture">Capturas e evoluções</option><option value="legend">Raros e extraordinários</option><option value="career">Carreira e conquistas</option><option value="bonds">Laços e arcos narrativos</option></select></div><div class="timeline" id="timeline"></div>`;$('filter-life').onchange=()=>timeline($('filter-life').value);timeline('all')}
function timeline(filter){let events=state.events.filter(e=>filter==='all'||filter==='bonds'&&['arc','relationship'].includes(e.kind)||filter==='major'&&e.major||filter==='capture'&&['capture','evolution','trade'].includes(e.kind)||filter==='legend'&&['legend','shiny'].includes(e.kind)||filter==='career'&&['career','competition','battle'].includes(e.kind));let prev=-1;let html='';for(const e of events){if(e.age!==prev){html+=`<div class="year">${e.age===0?'NASCIMENTO':e.age+' ANOS'} <span>${escape(E.phase(e.age).toUpperCase())}</span></div>`;prev=e.age}let source=e.source&&state.events.find(x=>x.id===e.source),visual=e.battle?[]:eventVisual(e);html+=`<article class="event ${e.major?'major':''} kind-${escape(e.kind)}"><div class="event-visual">${e.mystery?.stage==='incubating'?eggArt():e.mystery?.stage==='research'?fossilArt():visual.length?visual.map((v,i)=>`${i&&['evolution','trade'].includes(e.kind)?'<span class="evo-arrow">→</span>':''}<div class="event-mon">${image(v.id,v.shiny,'sprite')}<small>${escape(D.species[v.id].name)}</small></div>`).join(''):`<span class="event-symbol">${symbols[e.kind]||'◆'}</span>`}</div><div class="event-copy"><div class="event-meta"><span class="event-tag">${escape(kinds[e.kind]||e.kind)}</span> ${date(e.date)} · ${escape(city(e.city))}</div><h3>${escape(e.title)}</h3><p>${escape(N.text(e))}</p>${e.trade?tradeCard(e.trade):''}${e.battle?.award?`<div class="award-reveal">${badgeIcon(D.gyms.find(g=>g.id===e.battle.award.id),true)}<b>${escape(e.battle.award.name)}</b></div>`:''}${e.battle?`<details class="battle-history"><summary>Ver ${e.battle.duels.length} confronto(s)</summary>${e.battle.duels.map((d,i)=>duelCard(d,i)).join('')}</details>`:''}${source?`<span class="linked">↳ Memória conectada: ${escape(source.title)} (${date(source.date)})</span>`:''}</div></article>`}$('timeline').innerHTML=html||'<div class="empty">Nenhum acontecimento desta categoria até agora.</div>'}
function renderTeamPreview(){let arr=state.pokemon.filter(p=>p.status==='active');$('team-preview').innerHTML=`<div class="team-bar"><div><span class="eyebrow">EQUIPE / ${String(arr.length).padStart(2,'0')} DE 06</span><h2>Seu time Pokémon</h2></div><button id="go-team" class="ghost">Ver companheiros →</button></div><div class="party-grid">${Array.from({length:6},(_,i)=>{let p=arr[i];if(!p)return `<div class="party-slot empty-slot"><span class="ball"></span><small>Slot ${i+1} livre</small></div>`;let sp=D.species[p.id];return `<button class="party-slot ${p.shiny?'shiny':''}" data-party="${p.uid}" style="--type:${colors[sp.type]||'#8490a1'}"><span class="slot-number">${String(i+1).padStart(2,'0')} ${p.shiny?'✦ SHINY':''}</span>${image(p.id,p.shiny,'sprite',true)}<b>${escape(sp.name)}</b>${typeChip(sp)}</button>`}).join('')}</div>`;$('go-team').onclick=()=>{tab='team';renderTab();$('panel').scrollIntoView({block:'start',behavior:'smooth'})};document.querySelectorAll('[data-party]').forEach(b=>b.onclick=()=>detail(b.dataset.party))}
function pokeCard(p){let sp=D.species[p.id];return `<button class="poke ${p.shiny?'shiny':''}" data-uid="${p.uid}" type="button">${p.shiny?'<span class="spark">✦ Shiny</span>':''}${image(p.id,p.shiny)}<span class="dex-no">#${pad(p.id)}</span><b>${escape(sp.name)}</b><div class="poke-tags">${typeChip(sp)}${rarityChip(sp)}</div><small>${escape(p.nickname?'“'+p.nickname+'” · ':'')}${escape(p.personality)}</small><small>Desde os ${p.obtainedAge} anos</small>${meter(p.bond)}<small>Vínculo ${p.bond}/100</small></button>`}
function renderTeam(){let html='<h2>Seus companheiros</h2><p class="panel-intro">Clique em um Pokémon para ler sua trajetória individual. Nem todos precisam evoluir ou fazer parte do time.</p>';for(let k of Object.keys(status)){let arr=state.pokemon.filter(p=>p.status===k);html+=`<h3 class="section-title">${status[k]} · ${arr.length}${k==='active'?'/6':''}</h3>${arr.length?`<div class="poke-grid">${arr.map(pokeCard).join('')}</div>`:'<p class="empty">Nenhum companheiro nesta categoria.</p>'}`}$('panel').innerHTML=html;document.querySelectorAll('[data-uid]').forEach(b=>b.onclick=()=>detail(b.dataset.uid))}
const arcStatus={open:'Em andamento',fulfilled:'Promessa cumprida',closed:'Ciclo encerrado',interrupted:'Caminhos separados'};
function relationshipCards(snap,rows=snap.relationships||[]){return rows.length?`<div class="rel-grid">${rows.map(x=>{let p=snap.pokemon.find(p=>p.uid===x.a),q=snap.pokemon.find(p=>p.uid===x.b);if(!p||!q)return '';return `<article class="rel-card"><div class="rel-pair"><div>${image(p.id,p.shiny,'sprite')}<b>${escape(D.species[p.id].name)}</b></div><span class="rel-heart">${x.affinity>=65?'♥':'↔'}</span><div>${image(q.id,q.shiny,'sprite')}<b>${escape(D.species[q.id].name)}</b></div></div><h4>${escape(x.kind)}</h4>${p.status==='traded'||q.status==='traded'?'<small>Um dos companheiros vive com outro treinador.</small>':p.status==='released'||q.status==='released'?'<small>Um dos companheiros segue em liberdade.</small>':''}<div class="rel-stat"><span>Afinidade</span><b>${x.affinity}/100</b></div>${meter(x.affinity)}<div class="rel-stat"><span>Rivalidade</span><b>${x.rivalry}/100</b></div><div class="rival-meter">${meter(x.rivalry)}</div><details><summary>${x.steps.length} memória(s) compartilhada(s)</summary>${x.steps.map(y=>`<div class="rel-step"><b>${escape(y.title)}</b><small>${date(y.date)} · ${y.age} anos · ${escape(y.kind)}</small></div>`).join('')}</details></article>`}).join('')}</div>`:'<p class="empty">Ainda não há relações registradas entre companheiros.</p>'}
function arcCards(snap,cut,rows=snap.arcs||[]){let events=state.events.slice(0,cut+1),byId=new Map(events.map(e=>[e.id,e]));return rows.length?`<div class="arc-grid">${rows.map(a=>`<article class="arc-card ${a.status}"><div class="arc-top"><span>✧ ARCO DE VIDA</span><span class="arc-state">${escape(arcStatus[a.status])}</span></div><h3>${escape(a.title)}</h3><p class="arc-period">Desde os ${a.steps[0].age} anos${a.status!=='open'?' · até os '+a.steps.at(-1).age+' anos':''}</p><div class="arc-thread">${a.steps.map(step=>`<div class="arc-node"><span class="arc-dot"></span><div><small>${escape(step.stage)} · ${step.age} anos</small><b>${date(step.date)}</b><p>${escape(byId.get(step.eventId)?.text||step.title)}</p></div></div>`).join('')}${a.status==='open'?'<div class="arc-pending">Esta história ainda guarda perguntas.</div>':''}</div></article>`).join('')}</div>`:'<p class="empty">Nenhum arco iniciado até aqui.</p>'}
function bondsPanel(snap,cut){let arcs=snap.arcs||[],rels=snap.relationships||[];return `<div class="bonds-head"><span class="eyebrow">CADERNO DE MEMÓRIAS</span><h2>Laços e Memórias</h2><p>Algumas histórias duram anos. Algumas amizades começam com uma disputa.</p><div class="bonds-counts"><span><b>${arcs.length}</b> Histórias iniciadas</span><span><b>${arcs.filter(x=>x.status!=='open').length}</b> Ciclos encerrados</span><span><b>${rels.length}</b> Laços registrados</span></div></div><h3 class="section-title">Histórias que atravessam os anos</h3>${arcCards(snap,cut)}<h3 class="section-title">Relações entre Pokémon</h3>${relationshipCards(snap)}<h3 class="section-title">Biografias até aqui</h3><div class="bio-mini-grid">${snap.pokemon.map(p=>`<button type="button" class="bio-mini" data-bio="${p.uid}">${image(p.id,p.shiny,'sprite')}<b>${escape(D.species[p.id].name)}</b><small>${status[p.status]}</small></button>`).join('')||'<p>Nenhum companheiro registrado.</p>'}</div>`}
function bindBio(cut){document.querySelectorAll('[data-bio]').forEach(b=>b.onclick=()=>detail(b.dataset.bio,cut))}
function renderBonds(){let cut=state.events.length-1;$('panel').innerHTML=bondsPanel(state.events[cut].snapshot,cut);bindBio(cut)}
function detail(uid,cut=state.events.length-1){let p=E.biography(state,uid,cut);if(!p)return;let sp=D.species[p.id],snap=state.events[cut].snapshot;let origin=D.species[p.originId];$('detail-body').innerHTML=`<div class="detail-head">${image(p.id,p.shiny)}<div><span class="eyebrow">BIOGRAFIA DO COMPANHEIRO</span><h2>${escape(sp.name)} ${p.shiny?'✦':''}</h2><div class="poke-tags">${typeChip(sp)}${rarityChip(sp)}</div><p>${escape(p.nickname?'“'+p.nickname+'” · ':'')}${escape(p.personality)} · ${status[p.status]}</p><p>Desde ${date(p.obtained)} · ${escape(city(p.originCity))}</p></div></div><div class="bio-stat-grid"><div><b>${p.wins}</b><small>Vitórias</small></div><div><b>${p.losses}</b><small>Derrotas</small></div><div><b>${p.battleXP}</b><small>EXP de batalha</small></div><div><b>${p.years}</b><small>Anos desde o encontro</small></div></div><div class="bio-meters"><div><span>Vínculo · ${p.bond}/100</span>${meter(p.bond)}</div><div><span>Confiança · ${p.trust}/100</span>${meter(p.trust)}</div></div><h3 class="section-title">A vida que vocês compartilharam</h3><div class="bio-story">${N.bio(p,D).map(t=>`<p>${escape(t)}</p>`).join('')}</div>${p.feats.length?`<h3 class="section-title">Reputação e feitos</h3><div class="feat-list">${p.feats.map(f=>`<span>★ ${escape(f)}</span>`).join('')}</div>`:''}<h3 class="section-title">Linha evolutiva vivida</h3><div class="evo-line">${[p.originId,...p.evolutions.map(e=>e.to)].map((id,i)=>`${i?'<span>→</span>':''}<div>${image(id,p.shiny,'sprite')}<small>${escape(D.species[id].name)}</small>${i?`<small>${date(p.evolutions[i-1].date)}</small>`:''}</div>`).join('')}</div>${p.relations.length?`<h3 class="section-title">Seus laços com outros Pokémon</h3>${relationshipCards(snap,p.relations)}`:''}${p.arcs.length?`<h3 class="section-title">Histórias em que participou</h3>${arcCards(snap,cut,p.arcs)}`:''}<h3 class="section-title">Memórias marcantes</h3>${p.important.slice(-5).map(e=>`<div class="memory"><b>${escape(e.title)}</b><small>${date(e.date)} · ${e.age} anos</small><p>${escape(N.text(e))}</p></div>`).join('')||'<p class="panel-intro">Os pequenos momentos também fazem parte da jornada.</p>'}<h3 class="section-title">Histórico de duelos</h3>${p.duels.length?`<div class="bio-duels">${p.duels.map(d=>`<div class="bio-duel"><div>${image(d.player.id,d.player.shiny,'sprite')}<small>${escape(D.species[d.player.id].name)}</small></div><span>×</span><div>${image(d.opponent.id,d.opponent.shiny,'sprite')}<small>${escape(D.species[d.opponent.id].name)}</small></div><div><b class="${d.won?'won-text':'lost-text'}">${d.won?'Vitória':'Derrota'} · +${d.xp} EXP</b><small>${date(d.date)} · ${escape(d.rival)}</small><small>${escape(d.format)}</small></div></div>`).join('')}</div>`:'<p class="panel-intro">Ainda não participou de duelos.</p>'}<details class="bio-history"><summary>Diário completo deste companheiro (${p.history.length} registros)</summary>${p.history.map(e=>`<div class="memory"><b>${escape(e.title)}</b><small>${date(e.date)} · ${e.age} anos</small><p>${escape(N.text(e))}</p></div>`).join('')}</details>`;if(!$('detail').open)$('detail').showModal()}
$('detail').querySelector('.close').onclick=()=>$('detail').close();$('detail').addEventListener('click',e=>{if(e.target===$('detail'))$('detail').close()});
function renderDex(){$('panel').innerHTML=`<div class="toolbar"><div><h2>Pokédex pessoal</h2><p class="panel-intro">${state.encounters} avistamentos simulados; as evoluções também registram espécies.</p></div><input id="dex-search" type="search" placeholder="Buscar espécie" aria-label="Buscar espécie"><select id="dex-filter" aria-label="Filtrar espécies"><option value="all">Todas</option><option value="caught">Obtidas ou evoluídas</option><option value="shiny">Shiny</option><option value="legend">Extraordinárias</option></select></div><div id="dex-grid" class="poke-grid"></div>`;let draw=()=>{let q=$('dex-search').value.trim().toLowerCase(),f=$('dex-filter').value;let arr=Object.values(state.seen).filter(x=>D.species[x.id].name.toLowerCase().includes(q)&&(f==='all'||f==='caught'&&(x.caught||x.evolved)||f==='shiny'&&x.shiny||f==='legend'&&(D.species[x.id].legend||D.species[x.id].mythic))).sort((a,b)=>a.id-b.id);$('dex-grid').innerHTML=arr.map(x=>{let p=D.species[x.id];return `<div class="poke ${x.shiny?'shiny':''}">${x.shiny?'<span class="spark">✦</span>':''}${image(x.id,!!x.shiny,'sprite')}<span class="dex-no">#${pad(p.id)}</span><b>${escape(p.name)}</b><div class="poke-tags">${typeChip(p)}${rarityChip(p)}</div><small>${x.count} encontros · ${x.caught?x.caught+' capt.':x.evolved?'Evoluído':'Avistado'}</small><small>Desde ${date(x.first)}</small></div>`}).join('')||'<p class="empty">Nenhuma espécie corresponde ao filtro.</p>'};$('dex-search').oninput=draw;$('dex-filter').onchange=draw;draw()}
function renderProfile(){let af=Object.entries(state.affinity).sort((a,b)=>b[1]-a[1]);$('panel').innerHTML=`<h2>Quem você se tornou</h2><p class="panel-intro">Atributos fictícios do universo simulado, não uma avaliação de sua personalidade real.</p><div class="profile-grid"><div class="info"><h3>Personalidade atual</h3>${Object.entries(state.traits).map(([k,v])=>`<div class="trait"><span>${escape(k)}</span><b>${v}</b></div>${meter(v)}`).join('')}</div><div class="info"><h3>Caminhos profissionais</h3>${state.careerHistory.map(c=>`<div class="memory"><b>${escape(c.name)}</b><small>${c.age} anos · ${date(c.date)}</small></div>`).join('')||'<p>Ainda sem profissão definida.</p>'}<h3 class="section-title">Afinidades Pokémon</h3>${af.slice(0,6).map(([k,v])=>`<div class="trait"><span>${escape(k)}</span><b>${v}</b></div>${meter(Math.min(100,v*3))}`).join('')||'<p>Ainda em formação.</p>'}</div><div class="info"><h3>Memórias que moldaram seu destino</h3>${state.memories.map(m=>`<div class="memory"><b>${escape(m.title)}</b><small>${m.age} anos · ${escape(m.goal)}</small></div>`).join('')||'<p>As grandes memórias ainda estão por vir.</p>'}</div><div class="info"><h3>Pessoas que cruzaram seu caminho</h3>${state.friends.map(f=>`<div class="memory"><b>${escape(f.name)}</b><small>${escape(f.role)} · desde os ${f.age} anos · ${escape(city(f.city))}</small></div>`).join('')||'<p>Nenhuma amizade registrada ainda.</p>'}<h3 class="section-title">Conquistas</h3><p>${state.wins} vitórias · ${state.losses} derrotas · ${state.rescues} resgates</p></div></div>`}
function tradeCard(t){return `<article class="trade-card"><div class="trade-banner"><span>INTERCÂMBIO POKÉMON</span><b>${escape(t.partner)}</b><small>${escape(t.origin)} · ${escape(city(t.city))}</small></div><div class="trade-pair"><div>${image(t.out.id,t.out.shiny,'sprite',true)}<span class="trade-out">ENTREGUE</span><b>${escape(D.species[t.out.id].name)}${t.out.shiny?' ✦':''}</b><small>${escape(status[t.out.status])} → outro treinador</small></div><span class="trade-arrow">⇄</span><div>${image(t.in.id,t.in.shiny,'sprite',true)}<span class="trade-in">RECEBIDO</span><b>${escape(D.species[t.in.id].name)}${t.in.shiny?' ✦':''}</b><small>Destino: ${escape(status[t.in.status])}</small></div></div>${t.outside?'<div class="trade-rare">Espécie pouco habitual nos habitats desta cidade</div>':''}</article>`}
function worldPanel(cut){let events=state.events.slice(0,cut+1),snap=events.at(-1)?.snapshot,w=snap?.world||{news:[],items:[],trades:[],metLocals:[],reputation:{}},visited=new Set(events.map(e=>e.city));let map=D.mapPoints,paths=D.mapRoutes.map(([a,b])=>`<line x1="${map[a][0]*6}" y1="${map[a][1]*3.6}" x2="${map[b][0]*6}" y2="${map[b][1]*3.6}" class="${visited.has(a)&&visited.has(b)?'route-known':'route-unknown'}"/>`).join('');return `<div class="world-head"><span class="eyebrow">V1.5 · UM MUNDO VIVO</span><h2>Diário da Região</h2><p>O mundo até este momento da sua vida. Tudo aqui pertence ao universo fictício.</p></div><nav class="world-nav"><button data-world-jump="world-map">Mapa</button><button data-world-jump="world-news">Jornal</button><button data-world-jump="world-trades">Trocas (${w.trades.length})</button><button data-world-jump="world-items">Mochila</button><button data-world-jump="world-people">Pessoas</button></nav><section id="world-map" class="world-section"><h3>Mapa da jornada · ${visited.size}/10 cidades</h3><div class="region-map"><svg viewBox="0 0 600 350" role="img" aria-label="Mapa esquemático de rotas e cidades"><path d="M0 0H600V126L555 137L515 175L548 206L490 246L425 264L390 330L325 306L275 259L160 242L75 300L0 280Z" fill="#b9d6a0"/><path d="M120 205Q250 149 353 196Q305 260 180 236Z" fill="#83c7dd" stroke="#e9f9f8" stroke-width="3"/><path d="M0 54Q110 22 160 70T330 40" fill="none" stroke="#8cbb88" stroke-width="25" stroke-linecap="round" opacity=".6"/>${paths}${D.cities.map(c=>{let [x,y]=map[c.id].map((v,i)=>v*(i?3.6:6));return `<g class="map-node ${visited.has(c.id)?'known':''}" transform="translate(${x} ${y})"><circle r="12"/><text text-anchor="middle" y="4">${visited.has(c.id)?'●':'?'}</text></g>`}).join('')}</svg><div class="map-legend">● Cidade visitada &nbsp; · &nbsp; ? Ainda desconhecida &nbsp; · &nbsp; Rotas ilustrativas</div></div><div class="world-city-grid">${D.cities.filter(c=>visited.has(c.id)).map(c=>`<button class="ghost" data-city-mem="${c.id}">${escape(c.name)} · ${events.filter(e=>e.city===c.id).length}</button>`).join('')||'<p>Nenhuma cidade registrada.</p>'}</div><div id="city-memories" class="world-memories"></div></section><section id="world-news" class="world-section"><h3>Jornal das Lagoas</h3><div class="news-grid">${[...w.news].reverse().map(n=>`<article class="newspaper ${n.personal?'personal-news':''}"><div class="news-meta">${date(n.date)} · ${escape(city(n.city))}</div><span class="news-label">${n.personal?'SEU NOME NO JORNAL':escape(n.category.toUpperCase())}</span><h4>${escape(n.title)}</h4><p>${escape(n.text)}</p></article>`).join('')||'<p class="empty">Você ainda não leu nenhuma notícia.</p>'}</div></section><section id="world-trades" class="world-section"><h3>Histórico de trocas</h3><div class="world-trades">${[...w.trades].reverse().map(t=>`<div><p class="panel-intro">${date(t.date)} · ${t.age} anos</p>${tradeCard(t)}<div class="trade-links"><button class="ghost" data-world-bio="${t.out.uid}">Biografia de quem partiu</button><button class="ghost" data-world-bio="${t.in.uid}">Biografia de quem chegou</button></div></div>`).join('')||'<p class="empty">Nenhuma troca realizada até aqui.</p>'}</div></section><section id="world-items" class="world-section"><h3>Mochila de lembranças</h3><div class="item-grid">${w.items.map(i=>{let def=D.objects.find(x=>x.id===i.id);return `<div class="item-card">${def?.sprite?`<img src="https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/${def.sprite}.png" alt="" onerror="this.hidden=true"/>`:'<span class="item-symbol">◈</span>'}<b>${escape(i.name)}</b><small>${date(i.date)} · ${escape(city(i.city))}</small><small class="item-status">${escape(i.status)}${i.usedDate?' em '+date(i.usedDate):''}</small></div>`}).join('')||'<p class="empty">Sua mochila ainda está vazia.</p>'}</div></section><section id="world-people" class="world-section"><h3>Pessoas que você conheceu</h3><div class="world-people">${w.metLocals.map(n=>`<article>${image(n.id,false,'sprite')}<div><b>${escape(n.name)}</b><p>${escape(n.role)} · ${n.age} anos no encontro</p><small>${date(n.date)} · ${escape(city(n.city))}</small></div></article>`).join('')||'<p class="empty">Nenhum especialista conhecido até agora.</p>'}</div><h3>Reputação regional</h3>${Object.entries(w.reputation).map(([k,v])=>`<div class="trait"><span>${escape(k)}</span><b>${v}/100</b></div>${meter(v)}`).join('')}</section><section class="world-section"><h3>Calendário anual</h3><p class="panel-intro">Festivais públicos da região fictícia; não indica participação futura.</p><div class="festival-grid">${D.festivals.map(([id,t],i)=>`<div><small>${String(i+1).padStart(2,'0')}</small><b>${escape(t)}</b><span>${escape(city(id))}</span></div>`).join('')}</div></section>`}
function bindWorld(cut){document.querySelectorAll('[data-world-jump]').forEach(b=>b.onclick=()=>$(b.dataset.worldJump)?.scrollIntoView({behavior:'smooth',block:'start'}));document.querySelectorAll('[data-world-bio]').forEach(b=>b.onclick=()=>detail(b.dataset.worldBio,cut));document.querySelectorAll('[data-city-mem]').forEach(b=>b.onclick=()=>{let id=b.dataset.cityMem,c=D.cities.find(c=>c.id===id),ev=state.events.slice(0,cut+1).filter(e=>e.city===id);$('city-memories').innerHTML=`<h4>${escape(c.name)} · suas memórias</h4><p>${escape(c.tag)}</p><div class="place-list">${[...new Set(ev.map(e=>e.place))].map(x=>`<span>${escape(x)}</span>`).join('')}</div>${ev.slice(-12).reverse().map(e=>`<div class="memory"><b>${escape(e.title)}</b><small>${date(e.date)} · ${escape(e.place)}</small><p>${escape(N.text(e))}</p></div>`).join('')}`})}
function renderWorld(){let cut=state.events.length-1;$('panel').innerHTML=worldPanel(cut);bindWorld(cut)}
function inputFromState(universe=state.universe){return {name:state.name,birth:state.birth,cityId:state.cityId,personality:state.personality,universe}}
$('save').onclick=()=>persist(true);
$('load').onclick=()=>{try{let raw=localStorage.getItem(storage);if(!raw){toast('Nenhuma jornada salva neste navegador.');return}let saved=JSON.parse(raw);if(saved.version!==E.version){toast('A história foi criada com outra versão do motor.');return}let i=saved.input;$('name').value=i.name;$('birth').value=i.birth;$('city').value=i.cityId;$('personality').value=i.personality;generate(i,saved);toast('Jornada retomada.')}catch{toast('Não foi possível carregar a história.')}};
$('alternate').onclick=()=>{generate(inputFromState(state.universe+1));persist();toast('Você está em outro universo. O progresso anterior foi substituído neste dispositivo.');};$('reset').onclick=()=>{changeMode(false);$('result').hidden=true;$('welcome').hidden=false;window.scrollTo({top:0,behavior:'instant'})};
$('export').onclick=()=>{if(!finished)return;let lines=[`POKÉMON: DESTINOS DA COSTA — ${state.name}`,`${state.age} anos | ${state.city} | ${state.asOf} | Universo ${state.universe+1}`,`Motor ${state.version} | Seed ${state.seed}`,'','DIÁRIO DE VIDA',...state.events.flatMap(e=>[`${date(e.date)} · ${e.age} anos · ${e.title}`,N.text(e),...(e.battle?e.battle.duels.map(d=>`${D.species[d.player.id].name} × ${D.species[d.opponent.id].name}: ${d.won?'vitória':'derrota'} (+${d.xp} EXP)`):[]),'']),'COMPANHEIROS',...state.pokemon.map(p=>`${D.species[p.id].name}${p.shiny?' (shiny)':''} — ${status[p.status]} — desde ${date(p.obtained)} — vínculo ${p.bond}/100`),'','BIOGRAFIAS INDIVIDUAIS',...state.pokemon.flatMap(p=>{let b=E.biography(state,p.uid);return [D.species[p.id].name,...N.bio(b,D),...b.feats,'']}),'ARCOS DE VIDA',...state.arcs.flatMap(a=>[a.title+' — '+arcStatus[a.status],...a.steps.map(x=>`${date(x.date)} — ${state.events.find(e=>e.id===x.eventId)?.text||x.title}`),'']),'LAÇOS ENTRE POKÉMON',...state.relationships.map(x=>`${D.species[state.pokemon.find(p=>p.uid===x.a).id].name} × ${D.species[state.pokemon.find(p=>p.uid===x.b).id].name}: ${x.kind} (${x.affinity}/100 afinidade; ${x.rivalry}/100 rivalidade)`),'','TROCAS',...state.trades.map(t=>`${date(t.date)} — ${D.species[t.out.id].name} → ${D.species[t.in.id].name} (${t.partner}; ${status[t.in.status]})`),'','MOCHILA',...state.items.map(i=>`${i.name} — ${date(i.date)} — ${i.status}`),'','JORNAL',...state.news.map(n=>`${date(n.date)} — ${n.title}: ${n.text}`),'','Projeto de fã não oficial.'];let blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='destinos-da-costa-biografia.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Biografia exportada em texto.')};
// V1.7 interface: connected journeys have their own progress and storage.
let pairMode=false,pair=null,pairInput=null,pairCursor=0,pairStep=0,pairDone=false;
const pairStorage='destinos-da-costa-v201-dupla';
function eggArt(){return '<svg class="mystery-art" viewBox="0 0 120 140" role="img" aria-label="Ovo misterioso"><path d="M60 8C37 8 13 54 13 91a47 44 0 0 0 94 0C107 54 83 8 60 8Z" fill="#fff4d7" stroke="#586f72" stroke-width="4"/><path d="M44 37Q68 22 77 47T55 66Q34 60 44 37ZM16 81Q38 68 46 93T25 110ZM80 84Q103 78 103 101L82 120Q67 102 80 84Z" fill="#74b77a"/><path d="M40 20Q25 43 23 65" stroke="white" stroke-width="5" fill="none" stroke-linecap="round"/></svg>'}
function fossilArt(){return '<svg class="mystery-art" viewBox="0 0 120 120" role="img" aria-label="Fragmento fossilizado"><path d="M21 18L84 10 113 50 94 103 38 111 8 73Z" fill="#be9a72" stroke="#6d5748" stroke-width="4"/><path d="M70 85c-40 12-58-32-30-50 24-16 51 4 42 27-6 15-26 15-31 2-4-10 8-15 13-8" fill="none" stroke="#735d4b" stroke-width="8" stroke-linecap="round"/></svg>'}
function mysteryPanel(snap){let w=snap?.world||{},eggs=w.eggs||[],fossils=w.fossils||[],secrets=w.secrets||[];let statusMap={incubating:'Em incubação',hatched:'Eclodiu',research:'Em pesquisa',restored:'Restaurado',archived:'Preservado',open:'Em investigação',revealed:'Mistério revelado',unresolved:'Sem resposta'};let show=(uid)=>snap.pokemon.find(p=>p.uid===uid);return `<span class="eyebrow">CADERNO DE DESCOBERTAS</span><h2>Mistérios do destino</h2><p class="panel-intro">Apenas descobertas já vividas. Nem todo mistério precisa ter uma resposta.</p><h3>Ovos Pokémon</h3><div class="mystery-grid">${eggs.map(x=>{let m=show(x.hatchedUid);return `<article class="mystery-tile">${m?image(m.id,m.shiny,'sprite'):eggArt()}<b>${m?escape(D.species[m.id].name):'Ovo desconhecido'}</b><small>${statusMap[x.status]} · ${date(x.date)}</small><small>${escape(x.source)}</small></article>`}).join('')||'<p class="empty">Nenhum ovo registrado.</p>'}</div><h3>Fósseis</h3><div class="mystery-grid">${fossils.map(x=>{let m=show(x.restoredUid);return `<article class="mystery-tile">${m?image(m.id,m.shiny,'sprite'):fossilArt()}<b>${m?escape(D.species[m.id].name):'Fragmento antigo'}</b><small>${statusMap[x.status]} · ${date(x.date)}</small></article>`}).join('')||'<p class="empty">Nenhum fóssil registrado.</p>'}</div><h3>Investigações secretas</h3>${secrets.map(x=>`<div class="memory"><b>${escape(x.title)}</b><small>${statusMap[x.status]} · ${x.steps.length} pista(s)</small>${x.steps.map(t=>`<p>${date(t.date)} · ${escape(t.stage)}</p>`).join('')}</div>`).join('')||'<p class="empty">Nenhum mistério conhecido até aqui.</p>'}`}
function openMysteries(snap){$('detail-body').innerHTML=mysteryPanel(snap);$('detail').showModal()}
$('city-b').innerHTML=$('city').innerHTML;$('personality-b').innerHTML=$('personality').innerHTML;$('birth-b').max=E.today();
function changeMode(on){pairMode=on;$('second-trainer').hidden=!on;$('second-trainer').disabled=!on;$('mode-single').setAttribute('aria-pressed',String(!on));$('mode-pair').setAttribute('aria-pressed',String(on));}
$('mode-single').onclick=()=>changeMode(false);$('mode-pair').onclick=()=>changeMode(true);
function readPairInputs(){return {a:{name:$('name').value,birth:$('birth').value,cityId:$('city').value,personality:$('personality').value},b:{name:$('name-b').value,birth:$('birth-b').value,cityId:$('city-b').value,personality:$('personality-b').value},relation:$('relation').value}}
function startPair(input,saved=null){pair=E.simulatePair(input.a,input.b,{relation:input.relation});pairInput=input;pairCursor=0;pairStep=0;pairDone=false;if(saved){let pos=pair.timeline.findIndex(t=>pairKey(t)===saved.key);pairCursor=Math.max(0,pos);pairStep=Math.max(0,Math.min(Number(saved.step)||0,pairSteps(pair.timeline[pairCursor])));pairDone=!!saved.done&&pairCursor===pair.timeline.length-1; if(saved.done&&!pairDone&&pos>=0){pairCursor=Math.min(pos+1,pair.timeline.length-1);pairStep=0;}}$('welcome').hidden=true;$('result').hidden=true;$('pair-result').hidden=false;renderPair();savePair();window.scrollTo({top:0,behavior:'instant'})}
function pairKey(t){return t.shared||`${t.person}:${pair.people[t.person].events[t.index].id}`}
function pairSteps(t){if(t.shared)return pair.shared.find(x=>x.id===t.shared).battle?1:0;return battleSteps(pair.people[t.person].events[t.index].battle)}
function pairCuts(index,include){let cuts=[-1,-1];for(let i=0;i<=index-(include?0:1);i++){let t=pair.timeline[i];if(t.shared)t.indices.forEach((j,k)=>{if(j!=null)cuts[k]=Math.max(cuts[k],j)});else cuts[t.person]=Math.max(cuts[t.person],t.index)}return cuts;}
function pairMon(m){let sp=D.species[m.id];return `<div class="pair-mon">${image(m.id,m.shiny,'sprite',true)}<b>${escape(sp.name)}${m.shiny?' ✦':''}</b>${typeChip(sp)}</div>`}
function pairTeams(cuts,final=false){return `<div class="pair-teams">${pair.people.map((p,i)=>{let cut=cuts[i],snap=p.events[cut]?.snapshot,arr=snap?.pokemon.filter(q=>q.status==='active')||[];return `<article class="pair-team"><div class="pair-team-head"><span class="eyebrow">${i?'TREINADOR 02':'TREINADOR 01'}</span><h3>${escape(p.name)}</h3><small>${cut<0?'Ainda não nasceu':`${p.events[cut].age} anos · ${arr.length}/6 parceiros`}</small></div><div class="pair-party">${Array.from({length:6},(_,j)=>arr[j]?`<button data-pair-bio="${i}:${arr[j].uid}" class="pair-slot">${pairMon(arr[j])}</button>`:'<div class="pair-slot empty-slot"><span class="ball"></span><small>Vazio</small></div>').join('')}</div>${cut>=0?`<div class="pair-tools"><button data-pair-open="${i}:dex">Pokédex</button><button data-pair-open="${i}:bonds">Laços</button><button data-pair-open="${i}:league">Liga</button><button data-pair-open="${i}:world">Mundo</button><button data-pair-open="${i}:mystery">Mistérios</button>${final?`<button data-pair-open="${i}:full">Todos os companheiros</button><button data-pair-open="${i}:diary">Diário completo</button>`:''}</div>`:''}</article>`}).join('')}</div>`}
function pairSharedVisual(x,ended){if(x.type==='shared-egg')return eggArt();if(x.rareMon)return `<div class="pair-match">${pairMon(x.rareMon)}</div>`;if(x.trade)return `<div class="pair-match">${pairMon(x.trade.aOut)}<span class="vs">⇄</span>${pairMon(x.trade.bOut)}</div><p class="pair-caption">${escape(pair.people[0].name)} recebe ${escape(D.species[x.trade.aIn.id].name)} · ${escape(pair.people[1].name)} recebe ${escape(D.species[x.trade.bIn.id].name)}</p>`;if(x.battle){let b=x.battle;if(x.type==='duel')return `<div class="pair-match">${pairMon(b.a.player)}<span class="vs">VS</span>${pairMon(b.b.player)}</div>${ended?`<div class="pair-caption">${escape(b.a.won?pair.people[0].name:pair.people[1].name)} venceu! · +${b.a.xp} / +${b.b.xp} EXP</div>`:'<p class="pair-caption">Quem vai vencer?</p>'}`;return `<div class="pair-double">${[b.a,b.b].map((d,i)=>`<div class="pair-match">${pairMon(d.player)}<span class="vs">VS</span>${pairMon(d.opponent)}${ended?`<small class="pair-outcome ${d.won?'win':'loss'}">${d.won?'Vitória':'Derrota'} · +${d.xp} EXP</small>`:''}</div>`).join('')}</div>`}return '<span class="chapter-symbol">♥</span>'}
function pairIndividualVisual(e,ended){if(e.battle){let bs=battleState(e.battle,pairStep);return liveDuel(e.battle.duels[bs.idx],bs.idx,bs.turn,bs.revealed)}if(e.trade)return tradeCard(e.trade);if(e.mystery?.stage==='incubating')return eggArt();if(e.mystery?.stage==='research')return fossilArt();let v=eventVisual(e);return v.length?`<div class="pair-match">${v.map(pairMon).join('')}</div>`:`<span class="chapter-symbol">${symbols[e.kind]||'◆'}</span>`}
function renderPair(){let t=pair.timeline[pairCursor],ended=pairStep>=pairSteps(t),cuts=pairCuts(pairCursor,ended),x=t.shared?pair.shared.find(x=>x.id===t.shared):null,e=x?null:pair.people[t.person].events[t.index];text('pair-title',pair.people.map(p=>p.name).join(' × '));text('pair-subtitle',pairDone?'Duas vidas, uma história compartilhada':'Diário cronológico · sem antecipar o futuro');$('pair-export').hidden=!pairDone;let known=pair.shared.filter(s=>pair.timeline.slice(0,pairCursor+(ended?1:0)).some(t=>t.shared===s.id));let progress=Math.round((pairCursor+1)/pair.timeline.length*100);if(pairDone){cuts=pair.people.map(p=>p.events.length-1);$('pair-panel').innerHTML=`<div class="pair-final"><span class="eyebrow">JORNADA CONCLUÍDA</span><h2>As vidas que vocês construíram</h2><p>${pair.shared.length?`${pair.shared.length} memórias compartilhadas · vínculo final ${pair.shared.at(-1).bond}/100`:'As duas vidas ainda não se cruzaram.'}</p></div>${pairTeams(cuts,true)}<h3>Álbum de memórias em comum</h3>${pair.shared.map(s=>`<article class="memory"><b>${escape(s.title)}</b><small>${date(s.date)} · ${escape(city(s.city))}</small><p>${escape(N.text(s))}</p>${s.battle||s.trade||s.rareMon?pairSharedVisual(s,true):''}</article>`).join('')||'<p>Os dois caminhos ainda não se encontraram.</p>'}<button class="ghost" id="pair-reread">Reler jornada</button>`;$('pair-reread').onclick=()=>{pairDone=false;pairCursor=0;pairStep=0;renderPair();savePair()};}else{if(e)state=pair.people[t.person];$('pair-panel').innerHTML=`<div class="journey-progress"><div><b>${date(t.date)}</b><span>${x?'Memória compartilhada':escape(pair.people[t.person].name)+' · '+e.age+' anos'}</span></div><div><span>Capítulo ${pairCursor+1} de ${pair.timeline.length}</span>${meter(progress)}</div></div><article class="chapter-card pair-chapter ${x?'shared-chapter':''}"><div class="chapter-kicker"><span>${x?'DESTINOS CONECTADOS':escape(kinds[e.kind]||e.kind)}</span><span>${escape(city(x?x.city:e.city))}</span></div><h2>${escape(!ended&&(x?.battle||e?.battle)?'Um desafio na arena':x?x.title:N.title(e,D))}</h2>${chapterAtmosphere(x||e)}<div class="chapter-visual">${x?pairSharedVisual(x,ended):pairIndividualVisual(e,ended)}</div>${ended?`${storyCopy(x||e)}`:''}${x&&ended?`<div class="pair-bond">Vínculo entre vocês · ${x.bond}/100 ${meter(x.bond)}</div>${x.link?`<div class="pair-bond">${escape(D.species[x.link.a.id].name)} e ${escape(D.species[x.link.b.id].name)} · ${x.link.meetings} encontro(s)<br>Afinidade ${x.link.affinity}/100 · Rivalidade ${x.link.rivalry}/100</div>`:''}`:''}</article><div class="journey-controls"><button class="ghost" id="pair-prev" ${pairCursor===0&&pairStep===0?'disabled':''}>← Voltar</button>${ended&&pair.timeline.slice(pairCursor+1).some(q=>q.shared)?'<button class="ghost" id="pair-skip" title="Resume os capítulos individuais anteriores ao próximo encontro">Próximo encontro »</button>':''}<button class="primary" id="pair-next">${!ended?'Continuar batalha →':pairCursor===pair.timeline.length-1?'Revelar os destinos →':'Continuar jornada →'}</button></div>${pairTeams(cuts)}<p class="pair-caption">${known.length} memória(s) compartilhada(s) revelada(s).</p>`;$('pair-prev').onclick=()=>{stopBattlePlayback();if(pairStep>0)pairStep--;else if(pairCursor>0){pairCursor--;pairStep=pairSteps(pair.timeline[pairCursor])}renderPair();savePair()};if($('pair-skip'))$('pair-skip').onclick=()=>{stopBattlePlayback();let at=pair.timeline.findIndex((t,i)=>i>pairCursor&&t.shared);if(at>=0){pairCursor=at;pairStep=0;renderPair();savePair();}};$('pair-next').onclick=()=>{stopBattlePlayback();if(!ended)pairStep++;else if(pairCursor<pair.timeline.length-1){pairCursor++;pairStep=0}else pairDone=true;renderPair();savePair();if(!pairDone&&ended)focusChapter($('pair-panel'));if(pairDone)window.scrollTo({top:0,behavior:'instant'})};if(!ended)bindBattlePlayback($('pair-panel'),'pair:'+pairKey(t),()=>{pairStep++;renderPair();savePair()},()=>{pairStep=pairSteps(t);renderPair();savePair()});else stopBattlePlayback();let ve=x?(x.rareMon?[x.rareMon]:[]):(e.battle?[]:eventVisual(e));DC_VISUALS.decorate($('pair-panel'),x||e,x?null:pair.people[t.person].events[t.index-1]?.snapshot,ve,image,'pair:'+pair.people.map(p=>p.name+'|'+p.birth+'|'+p.cityId).join('|')+'|'+pairKey(t),!!x);}
 document.querySelectorAll('[data-pair-bio]').forEach(b=>b.onclick=()=>{let [i,uid]=b.dataset.pairBio.split(':');state=pair.people[i];detail(uid,cuts[i])});document.querySelectorAll('[data-pair-open]').forEach(b=>b.onclick=()=>{let [i,kind]=b.dataset.pairOpen.split(':');state=pair.people[i];let cut=cuts[i],snap=state.events[cut].snapshot;let body=$('detail-body');if(kind==='mystery')body.innerHTML=mysteryPanel(snap);else if(kind==='league')body.innerHTML=leaguePanel(snap);else if(kind==='bonds'){body.innerHTML=bondsPanel(snap,cut);bindBio(cut)}else if(kind==='world'){body.innerHTML=worldPanel(cut);bindWorld(cut)}else if(kind==='full'){body.innerHTML=`<h2>Companheiros de ${escape(state.name)}</h2><div class="poke-grid">${snap.pokemon.map(p=>`<button class="poke" data-bio="${p.uid}">${pairMon(p)}<small>${escape(status[p.status])}</small></button>`).join('')}</div>`;bindBio(cut)}else if(kind==='diary')body.innerHTML=`<h2>Diário de ${escape(state.name)}</h2>${state.events.slice(0,cut+1).map(e=>`<article class="memory"><b>${escape(e.title)}</b><small>${date(e.date)} · ${e.age} anos</small><p>${escape(N.text(e))}</p></article>`).join('')}`;else body.innerHTML=`<h2>Pokédex pessoal</h2><div class="poke-grid">${snap.seen.map(p=>`<div class="poke">${pairMon({...p,shiny:!!p.shiny})}</div>`).join('')}</div>`;$('detail').showModal()});}
function savePair(announce=false){try{localStorage.setItem(pairStorage,JSON.stringify({input:pairInput,version:E.version,key:pairKey(pair.timeline[pairCursor]),step:pairStep,done:pairDone}));if(announce)toast('Destinos salvos neste navegador.')}catch{if(announce)toast('Não foi possível salvar a dupla.')}}
$('pair-save').onclick=()=>savePair(true);$('pair-reset').onclick=()=>{changeMode(true);$('pair-result').hidden=true;$('welcome').hidden=false;window.scrollTo({top:0,behavior:'instant'})};$('load-pair').onclick=()=>{try{let v=JSON.parse(localStorage.getItem(pairStorage));if(!v||v.version!==E.version){toast('Nenhuma dupla salva nesta versão.');return}startPair(v.input,v);toast('Destinos retomados.')}catch{toast('Não foi possível carregar a dupla.')}};
$('pair-export').onclick=()=>{if(!pairDone)return;let lines=['DESTINOS CONECTADOS',pair.people.map(x=>x.name).join(' × '),'','MEMÓRIAS EM COMUM',...pair.shared.flatMap(x=>[`${date(x.date)} — ${x.title}`,N.text(x),'']),...pair.people.flatMap(p=>['',p.name,...p.events.flatMap(e=>[`${date(e.date)} — ${e.title}`,N.text(e),'']),'COMPANHEIROS',...p.pokemon.map(q=>`${D.species[q.id].name} — ${status[q.status]}`)])];let blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='destinos-conectados.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};

